<?php
require_once __DIR__ . '/../app/database.php';
if(isset($_GET['search'])||isset($_GET['category'])) { header('Location: catalog.php?'.http_build_query($_GET));exit; }
$banners=$conn->query('SELECT * FROM banners WHERE is_active=1 ORDER BY sort_order,id')->fetch_all(MYSQLI_ASSOC);
$new=$conn->query('SELECT * FROM products WHERE is_active=1 AND is_new=1 ORDER BY created_at DESC,id DESC LIMIT 4')->fetch_all(MYSQLI_ASSOC);
$featured=$conn->query('SELECT * FROM products WHERE is_active=1 AND is_featured=1 ORDER BY id DESC LIMIT 4')->fetch_all(MYSQLI_ASSOC);
$categories=$conn->query("SELECT p.category,c.count,p.image FROM products p JOIN (SELECT category,COUNT(*) count,MIN(id) first_id FROM products WHERE is_active=1 AND category<>'' GROUP BY category) c ON p.id=c.first_id ORDER BY p.category")->fetch_all(MYSQLI_ASSOC);
include __DIR__ . '/../app/views/layout/header.php';
